/* =========================================================================
 * Course — assets/app.js
 *
 * Hash-router SPA for the SMT & THT Process Engineer course.
 * CLASSIC SCRIPT ONLY (no ES modules) so it works from file:// and http.
 * Zero dependencies, zero build.
 *
 * Data: app.js tries fetch('data/*.json') first (works over http) and falls
 * back to the global COURSE_DATA from assets/data-embed.js (generated by
 * scripts/embed.js) so the course also works from file://.
 *
 * Security / contract rules (docs/CONTRACT.md):
 *   - every dynamic string goes through esc() before reaching innerHTML;
 *   - no inline event handlers — all events use addEventListener + delegation;
 *   - quiz grading is computed by this code at runtime; a lesson that is not
 *     reviewed still shows a visible draft banner.
 * ========================================================================= */
(function () {
  'use strict';

  var app = document.getElementById('main');
  if (!app) return;

  /* ------------------------------------------------------------------- esc */

  var ESC_MAP = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

  /** Escape &, <, >, ", ' — the ONLY path for dynamic text into innerHTML. */
  function esc(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, function (c) {
      return ESC_MAP[c];
    });
  }

  function safeDecode(s) { try { return decodeURIComponent(s); } catch (e) { return s; } }

  /* =========================================================================
   * Catalog constants — module titles, stage links and lesson durations come
   * from course/docs/curriculum.md (the curriculum is the source of truth for
   * module metadata; lessons.json carries lesson data only).
   * Generated from curriculum.md 2026-10-30; tests/embed.test.js + the course
   * checker keep the lesson ids in step with data/lessons.json.
   * ====================================================================== */

  var COURSE_TITLE = 'SMT & THT Process Engineer';
  var COURSE_DOC = 'C1.2 — curriculum (docs/curriculum.md)';

  // { id, n, stageId|null, title, competencies, lessons, prereq, pilot }
  var MODULES = [
    { id: 'm01', n: 1, stageId: 'incoming', title: 'Incoming Inspection', competencies: 'K1', lessons: 7, prereq: '—', pilot: false },
    { id: 'm02', n: 2, stageId: 'storage', title: 'Storage, MSL and ESD Control', competencies: 'K1', lessons: 6, prereq: 'm01', pilot: false },
    { id: 'm03', n: 3, stageId: 'stencil', title: 'Stencil Design and Verification', competencies: 'K2', lessons: 6, prereq: 'm01', pilot: false },
    { id: 'm04', n: 4, stageId: 'print', title: 'Solder Paste Printing and SPI', competencies: 'K3, K2, K6', lessons: 7, prereq: 'm03', pilot: true },
    { id: 'm05', n: 5, stageId: 'placement', title: 'Component Placement', competencies: 'K4', lessons: 6, prereq: 'm04', pilot: false },
    { id: 'm06', n: 6, stageId: 'reflow', title: 'Reflow Soldering', competencies: 'K5, K6', lessons: 7, prereq: 'm04', pilot: true },
    { id: 'm07', n: 7, stageId: 'aoi', title: 'AOI and X-ray Inspection', competencies: 'K6', lessons: 6, prereq: 'm04, m06', pilot: false },
    { id: 'm08', n: 8, stageId: 'tht-prep', title: 'THT: Preparation and Insertion', competencies: 'K7', lessons: 5, prereq: 'm02', pilot: false },
    { id: 'm09', n: 9, stageId: 'wave', title: 'Wave Soldering', competencies: 'K7, K6', lessons: 7, prereq: 'm08', pilot: true },
    { id: 'm10', n: 10, stageId: 'selective', title: 'Selective Soldering', competencies: 'K7, K5', lessons: 5, prereq: 'm09', pilot: false },
    { id: 'm11', n: 11, stageId: 'manual-rework', title: 'Manual Soldering and Rework', competencies: 'K8, K6', lessons: 6, prereq: 'm06, m02', pilot: false },
    { id: 'm12', n: 12, stageId: 'coating-esd', title: 'Cleaning and Conformal Coating', competencies: 'K1, K6', lessons: 6, prereq: 'm02, m06', pilot: false },
    { id: 'm13', n: 13, stageId: 'test', title: 'Test Strategy', competencies: 'K6, K10', lessons: 6, prereq: 'm07', pilot: false },
    { id: 'm14', n: 14, stageId: null, title: 'Defect Analysis and CAPA / 8D', competencies: 'K9, K6', lessons: 7, prereq: 'm04, m06, m07, m09', pilot: false },
    { id: 'm15', n: 15, stageId: null, title: 'Feedback to the Designer', competencies: 'K10, K2, K7', lessons: 5, prereq: 'm14', pilot: false }
  ];

  // lessonId -> planned minutes (curriculum.md lesson tables).
  var LESSON_MINUTES = {
    'm01l01': 20, 'm01l02': 25, 'm01l03': 30, 'm01l04': 30, 'm01l05': 25, 'm01l06': 25, 'm01l07': 20,
    'm02l01': 20, 'm02l02': 30, 'm02l03': 25, 'm02l04': 30, 'm02l05': 30, 'm02l06': 35,
    'm03l01': 25, 'm03l02': 35, 'm03l03': 25, 'm03l04': 35, 'm03l05': 30, 'm03l06': 25,
    'm04l01': 30, 'm04l02': 35, 'm04l03': 35, 'm04l04': 25, 'm04l05': 35, 'm04l06': 30, 'm04l07': 30,
    'm05l01': 25, 'm05l02': 30, 'm05l03': 35, 'm05l04': 30, 'm05l05': 25, 'm05l06': 35,
    'm06l01': 25, 'm06l02': 30, 'm06l03': 35, 'm06l04': 35, 'm06l05': 30, 'm06l06': 30, 'm06l07': 25,
    'm07l01': 25, 'm07l02': 30, 'm07l03': 30, 'm07l04': 35, 'm07l05': 25, 'm07l06': 35,
    'm08l01': 20, 'm08l02': 35, 'm08l03': 25, 'm08l04': 25, 'm08l05': 30,
    'm09l01': 25, 'm09l02': 25, 'm09l03': 30, 'm09l04': 35, 'm09l05': 30, 'm09l06': 35, 'm09l07': 25,
    'm10l01': 25, 'm10l02': 35, 'm10l03': 30, 'm10l04': 30, 'm10l05': 30,
    'm11l01': 25, 'm11l02': 30, 'm11l03': 35, 'm11l04': 30, 'm11l05': 25, 'm11l06': 30,
    'm12l01': 25, 'm12l02': 30, 'm12l03': 30, 'm12l04': 30, 'm12l05': 30, 'm12l06': 35,
    'm13l01': 25, 'm13l02': 30, 'm13l03': 25, 'm13l04': 30, 'm13l05': 35, 'm13l06': 30,
    'm14l01': 25, 'm14l02': 30, 'm14l03': 25, 'm14l04': 35, 'm14l05': 30, 'm14l06': 25, 'm14l07': 40,
    'm15l01': 25, 'm15l02': 30, 'm15l03': 35, 'm15l04': 30, 'm15l05': 25
  };

  var STATUS_LABEL = {
    draft: 'draft',
    factchecked: 'fact-checked',
    reviewed: 'reviewed',
    published: 'published'
  };

  /* --------------------------------------------------------------- storage */

  var STORE_KEY = 'dfm-course-progress-v1';
  var storageOk = true;

  function lsGet(key) { try { return window.localStorage.getItem(key); } catch (e) { storageOk = false; return null; } }
  function lsSet(key, value) { try { window.localStorage.setItem(key, value); return true; } catch (e) { storageOk = false; return false; } }

  var PASS_PCT = 80; // pass mark for lesson mastery and module exams

  function freshProgress() { return { v: 1, visited: {}, quiz: {}, exams: {} }; }

  function loadProgress() {
    var raw = lsGet(STORE_KEY);
    if (raw == null) return freshProgress();
    try {
      var p = JSON.parse(raw);
      if (p && typeof p === 'object' && !Array.isArray(p)) {
        return {
          v: 1,
          visited: (p.visited && typeof p.visited === 'object' && !Array.isArray(p.visited)) ? p.visited : {},
          quiz: (p.quiz && typeof p.quiz === 'object' && !Array.isArray(p.quiz)) ? p.quiz : {},
          exams: (p.exams && typeof p.exams === 'object' && !Array.isArray(p.exams)) ? p.exams : {}
        };
      }
    } catch (e) { /* corrupt -> start fresh */ }
    return freshProgress();
  }

  var progress = loadProgress();

  function saveProgress() { lsSet(STORE_KEY, JSON.stringify(progress)); }

  function markVisited(lessonId) {
    if (!progress.visited[lessonId]) {
      progress.visited[lessonId] = Date.now();
      saveProgress();
    }
  }

  function startedIn(moduleId) {
    var n = 0;
    for (var id in progress.visited) {
      if (Object.prototype.hasOwnProperty.call(progress.visited, id) &&
          id.slice(0, 3) === moduleId) n++;
    }
    return n;
  }

  function totalStarted() { return Object.keys(progress.visited).length; }

  // A lesson counts as mastered when the learner's best quiz result reaches
  // the pass mark — opening the page is not evidence of learning, grading is.
  function lessonMastered(lessonId) {
    var r = progress.quiz[lessonId];
    return !!(r && typeof r.best === 'number' && r.best >= PASS_PCT);
  }

  function masteredIn(moduleId) {
    var n = 0;
    lessonsOf(moduleId).forEach(function (l) { if (lessonMastered(l.lessonId)) n++; });
    return n;
  }

  function totalMastered() {
    var n = 0;
    LESSONS.forEach(function (l) { if (lessonMastered(l.lessonId)) n++; });
    return n;
  }

  function examRecord(moduleId) {
    var r = progress.exams[moduleId];
    return (r && typeof r.best === 'number') ? r : null;
  }

  /* ------------------------------------------------------------ data load */

  var LESSONS = [];
  var QUESTIONS = [];
  var SOURCES = [];
  var byLesson = {};
  var byQuestion = {};
  var bySource = {};
  var moduleLessons = {}; // moduleId -> lessons[]

  function indexData(lessons, questions, sources) {
    LESSONS = Array.isArray(lessons) ? lessons : [];
    QUESTIONS = Array.isArray(questions) ? questions : [];
    SOURCES = Array.isArray(sources) ? sources : [];
    byLesson = {}; byQuestion = {}; bySource = {}; moduleLessons = {};
    LESSONS.forEach(function (l) {
      if (!l || typeof l.lessonId !== 'string') return;
      byLesson[l.lessonId] = l;
      (moduleLessons[l.moduleId] = moduleLessons[l.moduleId] || []).push(l);
    });
    QUESTIONS.forEach(function (q) { if (q && q.questionId) byQuestion[q.questionId] = q; });
    SOURCES.forEach(function (s) { if (s && s.id) bySource[s.id] = s; });
  }

  function fetchJson(url) {
    return window.fetch(url, { cache: 'no-store' }).then(function (r) {
      if (!r || !r.ok) throw new Error(url + ' -> HTTP ' + (r && r.status));
      return r.json();
    });
  }

  // fetch first (http), embedded snapshot second (file://).
  function loadCourse(done) {
    function useEmbed(reason) {
      var cd = window.COURSE_DATA;
      if (cd && Array.isArray(cd.lessons)) {
        indexData(cd.lessons, cd.questions, cd.sources);
        done('embed', reason);
      } else {
        done('none', reason + '; assets/data-embed.js is missing — run `node scripts/embed.js`');
      }
    }

    if (typeof window.fetch !== 'function' || !window.Promise) {
      useEmbed('fetch unavailable');
      return;
    }
    window.Promise.all([
      fetchJson('data/lessons.json'),
      fetchJson('data/questions.json'),
      fetchJson('data/sources.json')
    ]).then(function (parts) {
      indexData(parts[0], parts[1], parts[2]);
      done('fetch', null);
    }).catch(function (e) {
      useEmbed('fetch failed (' + (e && e.message ? e.message : String(e)) + ')');
    });
  }

  /* -------------------------------------------------------------- helpers */

  function moduleById(id) {
    for (var i = 0; i < MODULES.length; i++) if (MODULES[i].id === id) return MODULES[i];
    return null;
  }

  function lessonsOf(moduleId) { return moduleLessons[moduleId] || []; }

  function moduleMinutes(moduleId) {
    var sum = 0;
    lessonsOf(moduleId).forEach(function (l) { sum += LESSON_MINUTES[l.lessonId] || 0; });
    return sum;
  }

  function lessonMinutes(lessonId) {
    var m = LESSON_MINUTES[lessonId];
    return typeof m === 'number' ? m : null;
  }

  function statusChip(status) {
    var label = STATUS_LABEL[status] || String(status || 'unknown');
    var cls = (status === 'reviewed' || status === 'published') ? 'chip chip--ok' : 'chip chip--draft';
    return '<span class="' + cls + '">' + esc(label) + '</span>';
  }

  function stageChip(stageId) {
    return ''; // internal stage ids stay out of the UI (contract ids, not user-facing)
  }

  /* ------------------------------------------------------- stage pipeline */

  // The 15 stages in line order, each with the 12px mono abbreviation
  // used by the pipeline strip.
  var PIPELINE_STAGES = [
    { id: 'incoming', label: 'IN' }, { id: 'storage', label: 'STO' },
    { id: 'stencil', label: 'STE' }, { id: 'print', label: 'PRT' },
    { id: 'placement', label: 'PLC' }, { id: 'reflow', label: 'REF' },
    { id: 'aoi', label: 'AOI' }, { id: 'tht-prep', label: 'THT' },
    { id: 'wave', label: 'WAV' }, { id: 'selective', label: 'SEL' },
    { id: 'manual-rework', label: 'MRW' }, { id: 'coating-esd', label: 'COA' },
    { id: 'test', label: 'TST' }, { id: 'shipping', label: 'SHI' },
    { id: 'capability', label: 'CAP' }
  ];

  // Geometry of the strip (viewBox units): 15 boxes of 48x26 on a 60-unit step.
  var PIPE_X0 = 2, PIPE_Y = 6, PIPE_W = 48, PIPE_H = 26, PIPE_STEP = 60;

  /**
   * Inline-SVG pipeline of the whole line with `activeStageId` highlighted.
   * Returns a string of markup (no DOM access). Everything interpolated here is
   * a constant from PIPELINE_STAGES — the argument is only compared against that
   * list, never written into the markup — so no escaping is needed.
   */
  function stagePipeline(activeStageId) {
    var active = -1;
    for (var i = 0; i < PIPELINE_STAGES.length; i++) {
      if (PIPELINE_STAGES[i].id === activeStageId) { active = i; break; }
    }
    var svg = '<svg class="pipeline-svg" viewBox="0 0 900 64" role="img" ' +
      'aria-label="Line pipeline: ' + esc(activeStageId || 'no stage') + ' active" ' +
      'xmlns="http://www.w3.org/2000/svg">';
    for (var s = 0; s < PIPELINE_STAGES.length; s++) {
      var x = PIPE_X0 + s * PIPE_STEP;
      var cx = x + PIPE_W / 2;
      var on = s === active;
      svg += '<rect class="pipe-box' + (on ? ' is-active' : '') + '" x="' + x + '" y="' + PIPE_Y +
        '" width="' + PIPE_W + '" height="' + PIPE_H + '" rx="8"/>';
      svg += '<text class="pipe-label' + (on ? ' is-active' : '') + '" x="' + cx + '" y="50" ' +
        'text-anchor="middle">' + PIPELINE_STAGES[s].label + '</text>';
      if (s < PIPELINE_STAGES.length - 1) {
        var ax = x + PIPE_W + 4;
        svg += '<line class="pipe-arrow" x1="' + ax + '" y1="19" x2="' + (ax + 4) + '" y2="19"/>' +
          '<polygon class="pipe-head" points="' + (ax + 4) + ',15 ' + (ax + 8) + ',19 ' + (ax + 4) + ',23"/>';
      }
    }
    return svg + '</svg>';
  }

  function pilotChip(m) { return ''; } // internal pilot status stays out of the learner UI

  function progressLine(started, mastered, total, minutes) {
    var s = esc(started) + '/' + esc(total) + ' lessons started · ' +
      esc(mastered) + '/' + esc(total) + ' mastered (quiz ≥ ' + esc(PASS_PCT) + '%)';
    if (minutes) s += ' · ≈' + esc(minutes) + ' min of planned study';
    return '<p class="progress-line">' + s + '</p>';
  }

  function progressBar(mastered, total) {
    var pct = total > 0 ? Math.round((mastered / total) * 100) : 0;
    return '<div class="progress" role="img" aria-label="' + esc(pct + '% mastered') +
      '"><span style="width:' + pct + '%"></span></div>';
  }

  function emptyBox(title, text) {
    return '<div class="empty"><p class="empty-title">' + esc(title) + '</p><p>' + esc(text) + '</p></div>';
  }

  function notFoundView(title, detail) {
    return '<header class="page-head"><h1 tabindex="-1">' + esc(title) + '</h1></header>' +
      '<p class="muted">' + esc(detail) + '</p>' +
      '<p><a class="btn btn--primary" href="#/">Back to module list</a></p>';
  }

  /* ------------------------------------------------------- view: modules #/ */

  function modulesView() {
    var startedAll = totalStarted();
    var html = '<section class="hero"><span class="hero-bg" aria-hidden="true"></span><div class="hero-inner">' +
      '<div class="hero-badges">' +
      '<span class="badge">' + esc(MODULES.length) + ' modules</span>' +
      '<span class="badge">' + esc(LESSONS.length) + ' lessons</span>' +
      '<span class="badge">' + esc(QUESTIONS.length) + ' quiz questions</span>' +
      '</div>' +
      '<h1 class="hero-title" tabindex="-1">SMT &amp; THT <span class="accent">Process Engineer</span></h1>' +
      '<p class="hero-lead">From incoming inspection to capability reporting — every stage of the line, ' +
      'one lesson at a time, each with a worked calculation and a real defect.</p>' +
      '<div class="hero-cta"><a class="btn btn--primary" href="#/l/m01l01">Start the course &#8594;</a></div>' +
      '</div></section>';

    html += '<div class="stats">' +
      '<div class="stat-card"><div class="stat-num">' + esc(LESSONS.length) + '</div>' +
      '<div class="stat-label">lessons across the full line — each with a worked calculation and a real defect</div></div>' +
      '<div class="stat-card"><div class="stat-num">' + esc(MODULES.length) + '</div>' +
      '<div class="stat-label">process stages covered, from incoming inspection to capability reporting</div></div>' +
      '<div class="stat-card"><div class="stat-num">' + esc(QUESTIONS.length) + '</div>' +
      '<div class="stat-label">quiz questions graded in-page by code</div></div>' +
      '</div>';

    html += '<h2>Course program</h2>';


    if (!storageOk) {
      html += '<div class="banner banner--info"><p class="flush">Progress cannot be stored in this ' +
        'browser (localStorage unavailable), so the started counts stay at zero for this session.</p></div>';
    }

    html += progressLine(startedAll, totalMastered(), LESSONS.length, null);
    html += progressBar(totalMastered(), LESSONS.length);

    html += '<ul class="module-list">';
    MODULES.forEach(function (m) {
      var ls = lessonsOf(m.id);
      var mastered = masteredIn(m.id);
      var mins = moduleMinutes(m.id);
      var passed = examRecord(m.id);
      html += '<li><a class="module-card" href="#/m/' + encodeURIComponent(m.id) + '">' +
        '<span class="module-card-head">' +
        '<span class="module-num">' + esc(pad2(m.n)) + '</span>' +
        '<span class="module-title">' + esc(m.title) + '</span>' +
        pilotChip(m) +
        '</span>' +
        '<span class="module-meta">' +
        '<span>' + esc(ls.length || m.lessons) + ' lessons</span>' +
        (mins ? '<span>&#8776;' + esc(mins) + ' min</span>' : '') +
        (mastered ? '<span class="module-progress">' + esc(mastered) + ' of ' +
          esc(ls.length || m.lessons) + ' mastered</span>' : '') +
        (passed && passed.best >= PASS_PCT ? '<span class="module-exam-pass">exam passed</span>' : '') +
        '</span></a></li>';
    });
    html += '</ul>';
    return html;
  }

  function pad2(n) { return (n < 10 ? '0' : '') + n; }

  /* ------------------------------------------------------ view: module #/m/ */

  function moduleView(moduleId) {
    var m = moduleById(moduleId);
    if (!m) {
      return notFoundView('Module not found', 'No module "' + moduleId + '" in the curriculum (' +
        COURSE_DOC + ').');
    }
    var ls = lessonsOf(moduleId);
    var started = startedIn(moduleId);
    var mastered = masteredIn(moduleId);

    var html = '<p class="kicker">Course program · Module ' + esc(pad2(m.n)) + '</p>';
    html += '<header class="page-head"><div><h1 tabindex="-1">' + esc(pad2(m.n) + ' — ' + m.title) + '</h1>' +
      '<div class="meta-line">' +
      stageChip(m.stageId) + pilotChip(m) +
      (m.prereq && m.prereq !== '—' ? '<span class="chip">prereq: ' +
        esc(m.prereq.replace(/^M(\d)$/, 'Module 0$1').replace(/^M(\d{2})$/, 'Module $1')) + '</span>' : '') +
      '</div></div></header>';

    html += progressLine(started, mastered, ls.length, moduleMinutes(moduleId));
    html += progressBar(mastered, ls.length);

    var examQs = moduleExamQuestions(moduleId);
    if (examQs.length) {
      var rec = examRecord(moduleId);
      var bankN = examBankFor(moduleId).length;
      html += '<section class="exam-card"><h2>Module exam</h2><p class="flush">' +
        esc(examQs.length) + ' question' + (examQs.length === 1 ? '' : 's') +
        (bankN ? ' randomly drawn from a bank of ' + esc(bankN) + '. ' : ' drawn from this module&#8217;s lessons. ') +
        'Pass mark: ' + esc(PASS_PCT) + '%.' +
        (rec ? ' Best result so far: ' + esc(rec.best) + '% — ' +
          (rec.best >= PASS_PCT ? 'passed.' : 'not passed yet.') : ' Not attempted yet.') +
        '</p><p class="flush"><a class="btn btn--primary" href="#/e/' +
        encodeURIComponent(moduleId) + '">' + (rec ? 'Retake the module exam' : 'Open the module exam') +
        ' &#8594;</a></p></section>';
    }

    if (!ls.length) {
      html += emptyBox('No lessons in the data yet',
        'data/lessons.json has no lessons for ' + moduleId + ' in this build.');
      return html;
    }

    html += '<ul class="lesson-list">';
    ls.forEach(function (l, i) {
      var mins = lessonMinutes(l.lessonId);
      var quizN = questionsFor(l).length;
      var visited = !!progress.visited[l.lessonId];
      html += '<li class="lesson-row' + (visited ? ' lesson-row--started' : '') + '">' +
        '<span class="lesson-num">' + esc(pad2(i + 1)) + '</span>' +
        '<div class="lesson-main">' +
        '<a class="lesson-title" href="#/l/' + encodeURIComponent(l.lessonId) + '">' + esc(l.title) + '</a>' +
        '<div class="lesson-meta">' +
        (mins != null ? '<span>' + esc(mins) + ' min</span>' : '') +
        (quizN ? '<span>' + esc(quizN) + ' quiz question' + (quizN === 1 ? '' : 's') + '</span>' : '') +
        '</div></div>' +
        '<div class="lesson-side"><a class="btn btn--small" href="#/l/' + encodeURIComponent(l.lessonId) + '">Open</a></div>' +
        '</li>';
    });
    html += '</ul>';
    return html;
  }

  /* ------------------------------------------------------ view: lesson #/l/ */

  function goalsHtml(lesson) {
    var goals = Array.isArray(lesson.goals) ? lesson.goals : [];
    if (!goals.length) return '';
    var html = '<section class="goals"><h2>What this lesson makes you able to do</h2><ol>';
    goals.forEach(function (g) {
      var comps = (g && Array.isArray(g.competencies)) ? g.competencies : [];
      html += '<li>' + esc(g && g.text ? g.text : '') + '</li>';
    });
    html += '</ol></section>';
    return html;
  }

  /* The learner-facing draft note. The internal review trace that used to sit
     under it was removed: it named the author's own working notes, which the
     learner cannot use and which read as a claim about verification. What
     remains is the honest statement of what the page is. */
  function draftBannerHtml(lesson) {
    if (lesson.status === 'reviewed' || lesson.status === 'published') return '';
    var html = '<div class="banner banner--warn banner--slim" role="note">' +
      '<p class="flush">This lesson is a draft: treat it as study notes, not as a work instruction. ' +
      'Numbers without a source reference are unverified.</p>';
    html += '</div>';
    return html;
  }

  function theoryHtml(content) {
    var theory = content && Array.isArray(content.theory) ? content.theory : [];
    var hasBlocks = !!(content && (Array.isArray(content.sections) || Array.isArray(content.blocks)));
    if (!theory.length && !hasBlocks) {
      return emptyBox('Theory not written yet',
        'This lesson is a curriculum placeholder: the goals are fixed, the text has not been drafted.');
    }
    if (!theory.length) return ''; // blocks-only lesson: sectionsHtml renders it
    var html = '<section class="theory"><h2>Theory</h2>';
    theory.forEach(function (t) {
      if (!t) return;
      // A theory entry may be a bare paragraph string. Rendering it as a
      // paragraph is deliberate: the alternative is that it silently
      // disappears, which is exactly what happened to m07l06.
      if (typeof t === 'string') { html += '<p>' + esc(t) + '</p>'; return; }
      if (t.h) html += '<h3>' + esc(t.h) + '</h3>';
      // A theory entry may carry rich blocks instead of (or with) plain paragraphs.
      if (Array.isArray(t.blocks)) html += blocksHtml(t.blocks);
      var paras = Array.isArray(t.p) ? t.p : [t.p];
      paras.forEach(function (p) {
        if (p) html += '<p>' + esc(p) + '</p>';
      });
    });
    html += '</section>';
    return html;
  }

  // The stored solution is one long "Step one: … Step two: …" string; render it
  // as an ordered list when it splits cleanly, otherwise as a paragraph.
  function solutionHtml(solution) {
    var parts = String(solution).split(/(?=\bStep\s+[a-z0-9]+:)/i).filter(function (s) {
      return s.trim().length > 0;
    });
    if (parts.length < 2) return '<p>' + esc(solution) + '</p>';
    var html = '<ol>';
    parts.forEach(function (p) {
      html += '<li>' + esc(p.trim().replace(/^Step\s+[a-z0-9]+:\s*/i, '')) + '</li>';
    });
    return html + '</ol>';
  }

  function calcHtml(content) {
    var calc = content && content.calc;
    if (!calc || (!calc.task && !calc.solution)) return '';
    var html = '<section class="calc"><h2>Calculation</h2>';
    if (calc.task) html += '<p class="calc-task">' + esc(calc.task) + '</p>';
    if (calc.solution) {
      html += '<details><summary>Show worked solution</summary><div class="details-body">' +
        solutionHtml(calc.solution) + '</div></details>';
    }
    html += '</section>';
    return html;
  }

  function defectHtml(content) {
    var d = content && content.defect;
    if (!d || (!d.symptom && !d.cause && !d.action)) return '';
    var steps = [['Symptom', d.symptom], ['Cause', d.cause], ['Action', d.action]];
    var html = '<section class="defect"><h2>Defect analysis: symptom → cause → action</h2><div class="defect-flow">';
    steps.forEach(function (s) {
      if (!s[1]) return;
      html += '<div class="defect-step"><span class="defect-label">' + esc(s[0]) + '</span>' +
        '<p>' + esc(s[1]) + '</p></div>';
    });
    html += '</div></section>';
    return html;
  }

  function sourcesHtml(lesson) {
    var refs = Array.isArray(lesson.sources) ? lesson.sources : [];
    var html = '<section class="sources"><details class="spoiler">' +
      '<summary>Sources' + (refs.length ? ' — ' + refs.length : '') + '</summary>' +
      '<div class="details-body">';
    if (!refs.length) {
      return html + '<p class="muted flush">No source is cited for this lesson yet. ' +
        'Contract rule: every number must cite a <code>src-…</code> entry.</p>' +
        '</div></details></section>';
    }
    html += '<ul>';
    refs.forEach(function (ref) {
      var s = bySource[ref];
      if (!s) {
        html += '<li><span class="src-id">' + esc(ref) + '</span> — <span class="muted">' +
          'unknown source id (not in data/sources.json)</span></li>';
        return;
      }
      var bits = [];
      if (s.edition) bits.push(esc(s.edition));
      if (s.section) bits.push('section ' + esc(s.section));
      if (s.type) bits.push(esc(s.type));
      html += '<li><span class="src-id">' + esc(ref) + '</span> <strong>' + esc(s.title) + '</strong>' +
        (bits.length ? ' — ' + bits.join(', ') : '') +
        '<span class="src-note">License: ' + esc(s.licenseNote || 'not stated') +
        ' · verified by ' + esc(s.verifiedBy || 'not stated') +
        (s.verifiedOn ? ' on ' + esc(s.verifiedOn) : '') + '</span>' +
        (s.currency ? '<span class="src-currency">' + esc(s.currency) + '</span>' : '') +
        '</li>';
    });
    return html + '</ul></div></details></section>';
  }

  /* ==================================================== lesson block renderer */
  /*
   * Rich content blocks. A content author puts them in data/lessons.json:
   *
   *   content.sections = [ { "h": "Section heading", "blocks": [ <block>, … ] }, … ]
   *   content.blocks   = [ <block>, … ]                    // flat alternative
   *   content.theory[i].blocks = [ <block>, … ]            // inside a theory entry
   *   // a sections[] entry may also BE a block: { "t": "callout", … }
   *
   * Block types (all text is escaped; check-course.js enforces these shapes):
   *   { t:'p',   text }                                  paragraph
   *   { t:'ul',  items:[string,…] }                     bulleted list
   *   { t:'ol',  items:[string,…] }                     numbered list
   *   { t:'h'|'h2'|'h3', text }                         heading
   *   { t:'table', caption?, head:[string,…], rows:[[string,…],…] }
   *   { t:'figure', svg:'<svg …</svg>', caption? }      inline SVG figure
   *   { t:'callout', kind:'note'|'warn'|'tip', title?, text|[text,…] }
   *   { t:'steps', items:[string,…] }                   numbered step list
   *
   * Raw-HTML policy: the ONLY value inserted without esc() is figure.svg. It is
   * accepted only when the whole field matches /^<svg[\s\S]*<\/svg>$/ and it
   * comes from data/lessons.json, a file authored in this repository and
   * human-reviewed before publication (it is never fetched from an untrusted
   * origin). Anything else falls back to escaped text so a malformed value can
   * still be read, and check-course.js rejects a non-conforming svg at commit
   * time.
   */

  var SVG_FIGURE_RE = /^<svg[\s\S]*<\/svg>$/;
  var CALLOUT_KINDS = ['note', 'warn', 'tip'];

  // 20px line icons, stroke currentColor (inherits the callout accent).
  var CALLOUT_ICONS = {
    note: '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" ' +
      'stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
      '<circle cx="12" cy="12" r="9"/><path d="M12 11v5"/><path d="M12 8h.01"/></svg>',
    warn: '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" ' +
      'stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
      '<path d="M10.3 4.2 2.6 17.5a2 2 0 0 0 1.7 3h15.4a2 2 0 0 0 1.7-3L13.7 4.2a2 2 0 0 0-3.4 0z"/>' +
      '<path d="M12 9.5v4"/><path d="M12 17h.01"/></svg>',
    tip: '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" ' +
      'stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
      '<path d="M12 3a6 6 0 0 0-3.5 10.9c.6.5 1 1.2 1.2 2h4.6c.2-.8.6-1.5 1.2-2A6 6 0 0 0 12 3z"/>' +
      '<path d="M9.5 19h5"/><path d="M10.5 21.5h3"/></svg>'
  };

  /** Paragraph text of a block: text, or p, or the block itself when a string. */
  function blockText(b) {
    if (b == null) return '';
    if (typeof b === 'string') return b;
    if (b.text != null) return b.text;
    if (b.p != null) return b.p;
    return '';
  }

  function listHtml(tag, items) {
    var arr = Array.isArray(items) ? items : [items];
    var html = '<' + tag + '>';
    arr.forEach(function (it) {
      if (it == null || it === '') return;
      html += '<li>' + esc(it) + '</li>';
    });
    return html + '</' + tag + '>';
  }

  function tableHtml(b) {
    var head = Array.isArray(b.head) ? b.head : [];
    var rows = Array.isArray(b.rows) ? b.rows : [];
    var html = '<figure class="tbl-wrap"><table class="tbl">';
    if (b.caption) html += '<caption>' + esc(b.caption) + '</caption>';
    if (head.length) {
      html += '<thead><tr>';
      head.forEach(function (h) { html += '<th scope="col">' + esc(h) + '</th>'; });
      html += '</tr></thead>';
    }
    html += '<tbody>';
    rows.forEach(function (r) {
      var cells = Array.isArray(r) ? r : [r];
      html += '<tr>';
      cells.forEach(function (c) { html += '<td>' + esc(c) + '</td>'; });
      html += '</tr>';
    });
    return html + '</tbody></table></figure>';
  }

  function figureHtml(b) {
    var svg = typeof b.svg === 'string' ? b.svg.trim() : '';
    var html = '<figure class="fig fig--zoomable">';
    // Trusted-data raw insert — see the raw-HTML policy above.
    if (SVG_FIGURE_RE.test(svg)) html += svg;
    else html += '<p class="fig-fallback">' + esc(svg || 'figure block: no inline SVG given') + '</p>';
    if (b.caption) html += '<figcaption>' + esc(b.caption) + '</figcaption>';
    return html + '</figure>';
  }

  function imageHtml(b) {
    var src = typeof b.src === 'string' ? b.src.trim() : '';
    var html = '<figure class="fig fig--photo">';
    if (src && !/^\s*javascript:/i.test(src)) {
      html += '<img src="' + esc(src) + '" alt="' + esc(b.alt || b.caption || '') +
        '" width="1280" height="896" loading="lazy">';
    } else {
      html += '<p class="fig-fallback">image block: no src given</p>';
    }
    if (b.caption) html += '<figcaption>' + esc(b.caption) + '</figcaption>';
    return html + '</figure>';
  }

  function calloutHtml(b) {
    var kind = CALLOUT_KINDS.indexOf(b.kind) !== -1 ? b.kind : 'note';
    var html = '<aside class="callout callout--' + kind + '">' +
      '<span class="callout-icon" aria-hidden="true">' + CALLOUT_ICONS[kind] + '</span>' +
      '<span class="callout-body">';
    if (b.title) html += '<p class="callout-title">' + esc(b.title) + '</p>';
    var paras = Array.isArray(b.text) ? b.text : [blockText(b)];
    paras.forEach(function (p) {
      if (p) html += '<p class="callout-text">' + esc(p) + '</p>';
    });
    return html + '</span></aside>';
  }

  /** One block -> markup. Unknown types degrade to a visible escaped note. */
  function blockHtml(b) {
    if (b == null || b === '') return '';
    if (typeof b === 'string') return '<p>' + esc(b) + '</p>';
    var t = b.t;
    if (t === 'p') return '<p>' + esc(blockText(b)) + '</p>';
    if (t === 'ul') return listHtml('ul', b.items);
    if (t === 'ol') return listHtml('ol', b.items);
    if (t === 'steps') return '<ol class="steps">' +
      (Array.isArray(b.items) ? b.items : []).map(function (s) {
        return '<li>' + esc(s) + '</li>';
      }).join('') + '</ol>';
    if (t === 'h2') return '<h2>' + esc(blockText(b)) + '</h2>';
    if (t === 'h' || t === 'h3') return '<h3>' + esc(blockText(b)) + '</h3>';
    if (t === 'table') return tableHtml(b);
    if (t === 'figure') return figureHtml(b);
    if (t === 'image') return imageHtml(b);
    if (t === 'callout') return calloutHtml(b);
    return '<p class="block-unknown muted">[' + esc(t || 'unknown block') + '] ' +
      esc(blockText(b)) + '</p>';
  }

  function blocksHtml(blocks) {
    if (!Array.isArray(blocks)) return '';
    var html = '';
    blocks.forEach(function (b) { html += blockHtml(b); });
    return html;
  }

  /** content.sections / content.blocks -> lesson markup. */
  function sectionsHtml(content) {
    if (!content || typeof content !== 'object') return '';
    var sections = Array.isArray(content.sections) ? content.sections : null;
    var flat = Array.isArray(content.blocks) ? content.blocks : null;
    if (!sections && !flat) return '';
    var html = '';
    if (sections) {
      sections.forEach(function (sec) {
        if (!sec) return;
        if (sec.t) { html += blockHtml(sec); return; }
        html += '<section class="lesson-section">';
        if (sec.h) html += '<h2>' + esc(sec.h) + '</h2>';
        html += blocksHtml(sec.blocks);
        html += '</section>';
      });
    }
    if (flat) html += '<section class="lesson-section">' + blocksHtml(flat) + '</section>';
    return html;
  }

  /* -------------------------------------------------------------- quiz ---- */

  var quizState = { lessonId: null, attempt: 0, answers: {}, submitted: false, results: null, notice: null };

  function resetQuiz(lessonId) {
    var attempt = (quizState.lessonId === lessonId ? quizState.attempt : 0) + 1;
    quizState = { lessonId: lessonId, attempt: attempt, answers: {}, submitted: false, results: null, notice: null };
  }

  /* Option order is a cue: with a fixed order the keyed answer sits in the same
     slot every time, so a learner can score without knowing the material.
     Options are therefore shown in a seeded order that depends on the question
     and the attempt, never on the stored key. Grading compares option ids, so
     the shuffle cannot change what counts as correct. */
  function strHash(s) {
    var h = 2166136261 >>> 0;
    for (var i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 16777619) >>> 0;
    }
    return h >>> 0;
  }

  function seededShuffle(list, seed) {
    var out = list.slice();
    var s = seed || 1;
    for (var i = out.length - 1; i > 0; i--) {
      s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
      var j = s % (i + 1);
      var t = out[i];
      out[i] = out[j];
      out[j] = t;
    }
    return out;
  }

  function displayOptions(q, attempt) {
    var opts = Array.isArray(q.options) ? q.options : [];
    if (opts.length < 2) return opts;
    return seededShuffle(opts, strHash(q.questionId + '#' + attempt));
  }

  function questionsFor(lesson) {
    var out = [];
    (Array.isArray(lesson.quiz) ? lesson.quiz : []).forEach(function (id) {
      if (byQuestion[id] && byQuestion[id].pool !== 'exam') out.push(byQuestion[id]);
    });
    if (!out.length) {
      QUESTIONS.forEach(function (q) {
        if (q && q.lessonId === lesson.lessonId && q.pool !== 'exam') out.push(q);
      });
    }
    return out;
  }

  function sourceLabel(ref) {
    var s = bySource[ref];
    if (!s) return String(ref || 'no source cited');
    return s.id + ' — ' + s.title + (s.edition ? ' (' + s.edition + ')' : '') +
      (s.currency ? ' — edition note in the lesson source list' : '');
  }

  function quizSectionHtml(lesson) {
    var qs = questionsFor(lesson);
    var html = '<section class="quiz" id="quiz"><h2>Quiz</h2>';
    if (!qs.length) {
      return html + '<p class="muted flush">No quiz questions exist for this lesson yet ' +
        '(data/questions.json). The quiz appears here as soon as questions are written.</p></section>';
    }

    if (quizState.submitted && quizState.results) {
      var r = quizState.results;
      html += '<p class="score ' + (r.score === r.total ? 'score--pass' : 'score--fail') +
        '" role="status">Score: ' + esc(r.score) + ' / ' + esc(r.total) + ' (' +
        esc(r.percent) + '%)' + (r.unanswered ? ' — ' + esc(r.unanswered) + ' left blank' : '') +
        (r.selfAssessed ? ' · ' + esc(r.selfAssessed) + ' open-response not auto-graded' : '') +
        '</p>';
    } else {
      html += '<p class="muted">' + esc(qs.length) + ' question' + (qs.length === 1 ? '' : 's') +
        '. Answer all of them, then check your answers — grading is done by the code in this page.</p>';
    }

    if (quizState.notice) {
      html += '<p class="banner banner--warn notice" role="status">' +
        esc(quizState.notice) + '</p>';
    }

    var graded = quizState.submitted && quizState.results;

    html += '<form class="quiz-form" data-lesson="' + esc(lesson.lessonId) + '" novalidate>';
    qs.forEach(function (q, i) {
      var chosen = quizState.answers[q.questionId];
      var correctId = q.correct;
      var opts = displayOptions(q, quizState.attempt);

      html += '<fieldset data-q="' + esc(q.questionId) + '">' +
        '<legend>' + esc('Question ' + (i + 1) + ' — ' + (q.type || 'single')) + '</legend>' +
        '<p class="q-prompt">' + esc(q.prompt) + '</p>';

      if (!opts.length) {
        // Open-response (e.g. type "case"): nothing to auto-grade.
        html += '<p class="muted">Open-response question — write your answer, then check to compare ' +
          'it with the reference explanation.</p>';
      } else {
        opts.forEach(function (o) {
          var cls = 'opt';
          var mark = '';
          if (graded) {
            if (o.id === correctId) { cls += ' opt--correct'; mark = '<span class="opt-mark">correct answer</span>'; }
            else if (o.id === chosen) { cls += ' opt--wrong'; mark = '<span class="opt-mark">your answer</span>'; }
            else cls += ' opt--muted';
          }
          html += '<label class="' + cls + '">' +
            '<input type="radio" name="' + esc('q-' + q.questionId) + '" value="' + esc(o.id) + '"' +
            (chosen === o.id ? ' checked' : '') + (graded ? ' disabled' : '') + '>' +
            '<span>' + esc(o.text) + '</span>' + mark + '</label>';
        });
      }

      if (graded) {
        html += '<p class="explain"><span class="explain-label">Why: </span>' +
          esc(q.explanation || 'no explanation recorded') +
          '<span class="src-note">Source: ' + esc(sourceLabel(q.source)) + '</span></p>';
      }
      html += '</fieldset>';
    });

    html += '<div class="quiz-actions">';
    if (graded) {
      html += '<button type="button" class="btn btn--primary" data-act="quiz-retake">Retake the quiz</button>';
    } else {
      html += '<button type="submit" class="btn btn--primary">Check answers</button>';
    }
    html += '</div></form></section>';
    return html;
  }

  function rerenderQuiz(lesson) {
    var host = document.getElementById('quiz');
    if (!host) return;
    host.outerHTML = quizSectionHtml(lesson);
  }

  /* Scrolling the score into view is a convenience, not part of grading. Some
     embedding environments do not implement Element.scrollIntoView (and older
     WebViews lack options), so a missing method must never abort the render
     that just wrote the result. */
  function scrollIntoViewQuietly(el) {
    if (!el || typeof el.scrollIntoView !== 'function') return;
    try { el.scrollIntoView({ block: 'nearest' }); } catch (e) { /* cosmetic */ }
  }

  function gradeQuiz(lesson) {
    var qs = questionsFor(lesson);
    var missing = 0, selfAssessed = 0;
    qs.forEach(function (q) {
      var opts = Array.isArray(q.options) ? q.options : [];
      if (!opts.length) { selfAssessed++; return; }
      if (!quizState.answers[q.questionId]) missing++;
    });

    if (missing) {
      quizState.notice = 'Answer every multiple-choice question before checking — ' + missing +
        ' still blank.';
      rerenderQuiz(lesson);
      // Focus the first option of the first unanswered question.
      var blanks = app.querySelectorAll('.quiz fieldset');
      for (var i = 0; i < blanks.length; i++) {
        if (!blanks[i].querySelector('input:checked')) {
          var firstBlank = blanks[i].querySelector('input');
          if (firstBlank) firstBlank.focus();
          break;
        }
      }
      return;
    }

    var score = 0, gradable = 0;
    var perQuestion = {};
    qs.forEach(function (q) {
      var opts = Array.isArray(q.options) ? q.options : [];
      if (!opts.length) return; // open-response: learner self-assesses
      gradable++;
      var ok = quizState.answers[q.questionId] === q.correct;
      perQuestion[q.questionId] = ok;
      if (ok) score++;
    });

    var total = gradable || qs.length;
    var percent = total ? Math.round((score / total) * 100) : 0;
    quizState.results = {
      score: score, total: total, percent: percent,
      unanswered: 0, selfAssessed: selfAssessed, perQuestion: perQuestion
    };
    quizState.submitted = true;
    quizState.notice = null;

    // Best score per lesson (progress only — never a verdict about the learner).
    var prev = progress.quiz[lesson.lessonId];
    if (!prev || typeof prev.best !== 'number' || percent > prev.best) {
      progress.quiz[lesson.lessonId] = { best: percent, total: total, at: Date.now() };
    } else {
      progress.quiz[lesson.lessonId].at = Date.now();
    }
    saveProgress();

    rerenderQuiz(lesson);
    var scoreEl = app.querySelector('.quiz .score');
    scrollIntoViewQuietly(scoreEl);
  }

  /* --------------------------------------------------- module exam -------- */

  var EXAM_SAMPLE_SIZE = 15;
  var examState = { moduleId: null, attempt: 0, answers: {}, submitted: false, results: null, notice: null, selection: null };

  function resetExam(moduleId) {
    var attempt = (examState.moduleId === moduleId ? examState.attempt : 0) + 1;
    examState = { moduleId: moduleId, attempt: attempt, answers: {}, submitted: false, results: null, notice: null, selection: null };
  }

  // Dedicated exam bank: questions tagged pool:"exam" that belong to this module's lessons.
  function examBankFor(moduleId) {
    var ids = {};
    lessonsOf(moduleId).forEach(function (l) { ids[l.lessonId] = true; });
    var out = [];
    QUESTIONS.forEach(function (q) {
      if (q && q.pool === 'exam' && ids[q.lessonId] && Array.isArray(q.options) && q.options.length) out.push(q);
    });
    return out;
  }

  // Freeze one random sample per attempt so re-renders keep the same questions.
  function ensureExamSelection(moduleId) {
    var bank = examBankFor(moduleId);
    if (!bank.length) return;
    if (examState.moduleId !== moduleId) resetExam(moduleId);
    if (!examState.selection || !examState.selection.length) {
      var shuffled = seededShuffle(bank, strHash(moduleId + '#exam#' + examState.attempt));
      examState.selection = shuffled.slice(0, Math.min(bank.length, EXAM_SAMPLE_SIZE))
        .map(function (q) { return q.questionId; });
    }
  }

  // With a dedicated bank the exam is a random sample from it; otherwise it falls
  // back to every auto-gradable question of the module's lessons (legacy data).
  function moduleExamQuestions(moduleId) {
    var bank = examBankFor(moduleId);
    if (bank.length) {
      if (examState.moduleId === moduleId && examState.selection && examState.selection.length) {
        var sel = [];
        examState.selection.forEach(function (id) { if (byQuestion[id]) sel.push(byQuestion[id]); });
        if (sel.length) return sel;
      }
      return bank.slice(0, Math.min(bank.length, EXAM_SAMPLE_SIZE));
    }
    var out = [];
    lessonsOf(moduleId).forEach(function (l) {
      questionsFor(l).forEach(function (q) {
        if (q && Array.isArray(q.options) && q.options.length) out.push(q);
      });
    });
    return out;
  }

  function examSectionHtml(moduleId) {
    var qs = moduleExamQuestions(moduleId);
    var html = '<section class="quiz" id="exam"><h2>Module exam</h2>';

    if (examState.submitted && examState.results) {
      var r = examState.results;
      var passed = r.percent >= PASS_PCT;
      html += '<p class="score ' + (passed ? 'score--pass' : 'score--fail') + '" role="status">Score: ' +
        esc(r.score) + ' / ' + esc(r.total) + ' (' + esc(r.percent) + '%) — ' +
        (passed ? 'passed' : 'not passed (pass mark ' + PASS_PCT + '%)') + '</p>';
      if (!passed) {
        html += '<p class="banner banner--warn flush" role="note">Review the explanations below and ' +
          'the lessons of this module, then retake the exam. Your best result is kept.</p>';
      }
    } else {
      var fromBank = examBankFor(moduleId).length > 0;
      html += '<p class="muted">' + esc(qs.length) + (fromBank ?
        ' questions randomly drawn from this module&#8217;s exam bank. ' : ' questions from this module&#8217;s lessons. ') +
        'Answer all of them, then submit — pass mark is ' + esc(PASS_PCT) + '%. ' +
        'Grading is done by the code in this page.</p>';
    }

    if (examState.notice) {
      html += '<p class="banner banner--warn notice" role="status">' + esc(examState.notice) + '</p>';
    }

    var graded = examState.submitted && examState.results;

    html += '<form class="quiz-form exam-form" data-module="' + esc(moduleId) + '" novalidate>';
    qs.forEach(function (q, i) {
      var chosen = examState.answers[q.questionId];
      var correctId = q.correct;
      var opts = displayOptions(q, examState.attempt);

      html += '<fieldset data-q="' + esc(q.questionId) + '">' +
        '<legend>' + esc('Question ' + (i + 1)) + '</legend>' +
        '<p class="q-prompt">' + esc(q.prompt) + '</p>';

      opts.forEach(function (o) {
        var cls = 'opt';
        var mark = '';
        if (graded) {
          if (o.id === correctId) { cls += ' opt--correct'; mark = '<span class="opt-mark">correct answer</span>'; }
          else if (o.id === chosen) { cls += ' opt--wrong'; mark = '<span class="opt-mark">your answer</span>'; }
          else cls += ' opt--muted';
        }
        html += '<label class="' + cls + '">' +
          '<input type="radio" name="' + esc('e-' + q.questionId) + '" value="' + esc(o.id) + '"' +
          (chosen === o.id ? ' checked' : '') + (graded ? ' disabled' : '') + '>' +
          '<span>' + esc(o.text) + '</span>' + mark + '</label>';
      });

      if (graded) {
        html += '<p class="explain"><span class="explain-label">Why: </span>' +
          esc(q.explanation || 'no explanation recorded') +
          '<span class="src-note">Source: ' + esc(sourceLabel(q.source)) + '</span></p>';
      }
      html += '</fieldset>';
    });

    html += '<div class="quiz-actions">';
    if (graded) {
      html += '<button type="button" class="btn btn--primary" data-act="exam-retake">Retake the exam</button>';
    } else {
      html += '<button type="submit" class="btn btn--primary">Submit exam</button>';
    }
    html += '</div></form></section>';
    return html;
  }

  function examView(moduleId) {
    var m = moduleById(moduleId);
    if (!m) {
      return notFoundView('Module not found', 'No module "' + moduleId + '" in the curriculum (' +
        COURSE_DOC + ').');
    }
    if (examState.moduleId !== moduleId) resetExam(moduleId);
    ensureExamSelection(moduleId);
    var qs = moduleExamQuestions(moduleId);
    if (!qs.length) {
      return notFoundView('No exam questions', 'data/questions.json has no gradable questions for ' +
        moduleId + ' yet.');
    }

    var html = '<p class="kicker">Course program · Module ' + esc(pad2(m.n)) + '</p>';
    html += '<header class="page-head"><div><h1 tabindex="-1">' +
      esc(pad2(m.n) + ' — ' + m.title + ' · Module exam') + '</h1></div></header>';
    html += examSectionHtml(moduleId);
    html += '<p><a class="btn" href="#/m/' + encodeURIComponent(moduleId) + '">&#8592; Back to module ' +
      esc(pad2(m.n)) + '</a></p>';
    return html;
  }

  function rerenderExam(moduleId) {
    var host = document.getElementById('exam');
    if (!host) return;
    host.outerHTML = examSectionHtml(moduleId);
  }

  function gradeExam(moduleId) {
    ensureExamSelection(moduleId);
    var qs = moduleExamQuestions(moduleId);
    var missing = 0;
    qs.forEach(function (q) { if (!examState.answers[q.questionId]) missing++; });

    if (missing) {
      examState.notice = 'Answer every question before submitting — ' + missing + ' still blank.';
      rerenderExam(moduleId);
      var blanks = app.querySelectorAll('#exam fieldset');
      for (var i = 0; i < blanks.length; i++) {
        if (!blanks[i].querySelector('input:checked')) {
          var firstBlank = blanks[i].querySelector('input');
          if (firstBlank) firstBlank.focus();
          break;
        }
      }
      return;
    }

    var score = 0;
    qs.forEach(function (q) { if (examState.answers[q.questionId] === q.correct) score++; });
    var total = qs.length;
    var percent = total ? Math.round((score / total) * 100) : 0;
    examState.results = { score: score, total: total, percent: percent };
    examState.submitted = true;
    examState.notice = null;

    var prev = progress.exams[moduleId];
    if (!prev || typeof prev.best !== 'number' || percent > prev.best) {
      progress.exams[moduleId] = { best: percent, total: total, at: Date.now() };
    } else {
      progress.exams[moduleId].at = Date.now();
    }
    saveProgress();

    rerenderExam(moduleId);
    var scoreEl = app.querySelector('#exam .score');
    scrollIntoViewQuietly(scoreEl);
  }

  /* ------------------------------------------------- lesson view continued */

  function pagerHtml(lesson) {
    var idx = -1;
    for (var i = 0; i < LESSONS.length; i++) {
      if (LESSONS[i].lessonId === lesson.lessonId) { idx = i; break; }
    }
    if (idx < 0) return '';
    var prev = idx > 0 ? LESSONS[idx - 1] : null;
    var next = idx < LESSONS.length - 1 ? LESSONS[idx + 1] : null;
    if (!prev && !next) return '';
    var html = '<nav class="pager" aria-label="Lesson navigation">';
    if (prev) {
      html += '<a href="#/l/' + encodeURIComponent(prev.lessonId) + '" class="pager-prev">' +
        '<span class="pager-label">← Previous</span>' +
        '<span class="pager-title">' + esc(prev.title) + '</span></a>';
    }
    if (next) {
      html += '<a href="#/l/' + encodeURIComponent(next.lessonId) + '" class="pager-next">' +
        '<span class="pager-label">Next →</span>' +
        '<span class="pager-title">' + esc(next.title) + '</span></a>';
    }
    return html + '</nav>';
  }

  function lessonView(lessonId) {
    var lesson = byLesson[lessonId];
    if (!lesson) {
      return notFoundView('Lesson not found', 'No lesson "' + lessonId + '" in data/lessons.json.');
    }
    markVisited(lessonId);
    if (quizState.lessonId !== lessonId) resetQuiz(lessonId);

    var m = moduleById(lesson.moduleId);
    var mins = lessonMinutes(lesson.lessonId);
    var content = lesson.content || null;

    var html = '';
    if (m) html += '<p class="kicker">Module ' + esc(pad2(m.n)) + ' · ' + esc(m.title) + '</p>';

    var ls = lessonsOf(lesson.moduleId);
    var lnum = 1;
    for (var li = 0; li < ls.length; li++) {
      if (ls[li].lessonId === lesson.lessonId) { lnum = li + 1; break; }
    }
    html += '<header class="page-head"><div><h1 tabindex="-1">' + esc(lesson.title) + '</h1>' +
      '<div class="meta-line">' +
      '<span class="chip">Lesson ' + esc(pad2(lnum)) + '</span>' +
      (mins != null ? '<span class="chip">' + esc(mins) + ' min</span>' : '') +
      stageChip(lesson.stageId) +
      '</div></div></header>';

    // Line-position strip: shown for any lesson attached to a stage.
    if (lesson.stageId) html += '<div class="pipeline">' + stagePipeline(lesson.stageId) + '</div>';

    html += draftBannerHtml(lesson);
    html += goalsHtml(lesson);
    html += theoryHtml(content);
    html += sectionsHtml(content);
    html += calcHtml(content);
    html += defectHtml(content);
    html += quizSectionHtml(lesson);
    html += sourcesHtml(lesson);
    html += pagerHtml(lesson);
    return html;
  }

  /* ------------------------------------------------- sidebar & topbar chrome */

  function renderSidebar() {
    var pct = LESSONS.length ? Math.round((totalMastered() / LESSONS.length) * 100) : 0;
    var pctEl = document.getElementById('side-pct');
    var barEl = document.getElementById('side-bar');
    if (pctEl) pctEl.textContent = pct + '%';
    if (barEl) barEl.style.width = pct + '%';

    var toc = document.getElementById('toc');
    if (!toc) return;
    var activeModule = route.view === 'module' ? route.moduleId :
      (route.view === 'lesson' && byLesson[route.lessonId] ? byLesson[route.lessonId].moduleId : null);
    var activeLesson = route.view === 'lesson' ? route.lessonId : null;
    var html = '';
    MODULES.forEach(function (m) {
      var active = m.id === activeModule;
      html += '<a class="toc-mod' + (active ? ' toc-mod--active' : '') + '" href="#/m/' +
        encodeURIComponent(m.id) + '"><span class="toc-mod-num">' + esc(pad2(m.n)) +
        '</span><span class="toc-mod-title">' + esc(m.title) + '</span></a>';
      if (active) {
        var ls = lessonsOf(m.id);
        if (ls.length) {
          html += '<ul class="toc-lessons">';
          ls.forEach(function (l) {
            var cls = 'toc-lesson';
            if (progress.visited[l.lessonId]) cls += ' toc-lesson--visited';
            if (lessonMastered(l.lessonId)) cls += ' toc-lesson--mastered';
            if (l.lessonId === activeLesson) cls += ' toc-lesson--active';
            html += '<li><a class="' + cls + '" href="#/l/' + encodeURIComponent(l.lessonId) +
              '">' + esc(l.title) + '</a></li>';
          });
          html += '</ul>';
        }
        if (moduleExamQuestions(m.id).length) {
          var examCls = 'toc-exam';
          var erec = examRecord(m.id);
          if (erec && erec.best >= PASS_PCT) examCls += ' toc-exam--passed';
          if (route.view === 'exam' && route.moduleId === m.id) examCls += ' toc-exam--active';
          html += '<a class="' + examCls + '" href="#/e/' + encodeURIComponent(m.id) +
            '">Module exam' + (erec && erec.best >= PASS_PCT ? ' &#10003;' : '') + '</a>';
        }
      }
    });
    toc.innerHTML = html;
  }

  function renderTopbar() {
    var el = document.getElementById('topbar-crumb');
    if (!el) return;
    var html = '<a href="#/">Process Engineer</a>';
    if (route.view === 'module') {
      var m = moduleById(route.moduleId);
      if (m) html += '<span class="sep">·</span>Module ' + esc(pad2(m.n)) + ' · <strong>' + esc(m.title) + '</strong>';
    } else if (route.view === 'exam') {
      var em = moduleById(route.moduleId);
      if (em) html += '<span class="sep">·</span><a href="#/m/' + encodeURIComponent(em.id) +
        '">Module ' + esc(pad2(em.n)) + ' · ' + esc(em.title) + '</a>';
      html += '<span class="sep">&#8594;</span><strong>Module exam</strong>';
    } else if (route.view === 'lesson') {
      var l = byLesson[route.lessonId];
      if (l) {
        var mm = moduleById(l.moduleId);
        if (mm) html += '<span class="sep">·</span><a href="#/m/' + encodeURIComponent(mm.id) +
          '">Module ' + esc(pad2(mm.n)) + ' · ' + esc(mm.title) + '</a>';
        html += '<span class="sep">&#8594;</span><strong>' + esc(l.title) + '</strong>';
      }
    }
    el.innerHTML = html;
  }

  /* --------------------------------------------------------------- router */

  var route = { view: 'modules' };

  function parseHash() {
    var h = window.location.hash || '#/';
    var m;
    if (h === '#/' || h === '#' || h === '') return { view: 'modules' };
    if ((m = h.match(/^#\/m\/([^\/?#]+)$/))) return { view: 'module', moduleId: safeDecode(m[1]).toLowerCase() };
    if ((m = h.match(/^#\/l\/([^\/?#]+)$/))) return { view: 'lesson', lessonId: safeDecode(m[1]).toLowerCase() };
    if ((m = h.match(/^#\/e\/([^\/?#]+)$/))) return { view: 'exam', moduleId: safeDecode(m[1]).toLowerCase() };
    return { view: 'notfound', hash: h };
  }

  function render() {
    if (!DATA_OK) return;
    route = parseHash();
    var html;
    var title = COURSE_TITLE;

    if (route.view === 'modules') {
      html = modulesView();
    } else if (route.view === 'module') {
      html = moduleView(route.moduleId);
      var mm = moduleById(route.moduleId);
      if (mm) title = 'Module ' + pad2(mm.n) + ' — ' + mm.title;
    } else if (route.view === 'lesson') {
      html = lessonView(route.lessonId);
      var ll = byLesson[route.lessonId];
      if (ll) title = ll.title;
    } else if (route.view === 'exam') {
      html = examView(route.moduleId);
      var me = moduleById(route.moduleId);
      if (me) title = 'Module ' + pad2(me.n) + ' exam — ' + me.title;
    } else {
      html = notFoundView('Page not found', 'Unrecognised address "' + route.hash + '".');
      title = 'Not found';
    }

    app.innerHTML = html;
    // Hide photo figures whose file is not on disk yet (no inline handler: CSP-safe).
    Array.prototype.forEach.call(app.querySelectorAll('.fig--photo img'), function (im) {
      im.addEventListener('error', function () {
        var fig = im.closest('.fig');
        if (fig) fig.parentNode.removeChild(fig);
      });
    });
    document.title = title + ' · SMTInsider Course';
    renderSidebar();
    renderTopbar();
    window.scrollTo(0, 0);

    var h1 = app.querySelector('h1');
    if (h1) h1.focus();
  }

  /* ---------------------------------------------------------- event wiring */

  app.addEventListener('change', function (e) {
    var el = e.target;
    if (!el || !el.name) return;
    if (el.name.indexOf('q-') === 0) {
      if (el.checked) quizState.answers[el.name.slice(2)] = el.value;
    } else if (el.name.indexOf('e-') === 0) {
      if (el.checked) examState.answers[el.name.slice(2)] = el.value;
    }
  });

  app.addEventListener('submit', function (e) {
    var form = e.target;
    if (!form || !form.classList || !form.classList.contains('quiz-form')) return;
    e.preventDefault();
    if (form.classList.contains('exam-form')) {
      gradeExam(form.getAttribute('data-module'));
      return;
    }
    var lesson = byLesson[form.getAttribute('data-lesson')];
    if (lesson) gradeQuiz(lesson);
  });

  app.addEventListener('click', function (e) {
    var btn = e.target && e.target.closest ? e.target.closest('[data-act]') : null;
    if (!btn) return;
    var act = btn.getAttribute('data-act');
    if (act === 'quiz-retake') {
      var lesson = byLesson[quizState.lessonId];
      if (!lesson) return;
      resetQuiz(lesson.lessonId);
      rerenderQuiz(lesson);
      var first = app.querySelector('.quiz input[type=radio]');
      if (first) first.focus();
    } else if (act === 'exam-retake') {
      if (!examState.moduleId) return;
      resetExam(examState.moduleId);
      rerenderExam(examState.moduleId);
      var firstE = app.querySelector('#exam input[type=radio]');
      if (firstE) firstE.focus();
    }
  });

  // Illustration zoom: click the image to enlarge it over a dimmed backdrop,
  // click again (anywhere on the enlarged figure) to return it to place.
  app.addEventListener('click', function (e) {
    var fig = e.target && e.target.closest ? e.target.closest('.fig--photo, .fig--zoomable') : null;
    if (!fig) return;
    if (fig.classList.contains('is-zoomed')) {
      fig.classList.remove('is-zoomed');
      return;
    }
    var onMedia = e.target.tagName === 'IMG' ||
      (e.target.closest && e.target.ownerSVGElement !== undefined && e.target.closest('svg'));
    if (onMedia) fig.classList.add('is-zoomed');
  });

  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    var zoomed = app.querySelector('.fig--photo.is-zoomed, .fig--zoomable.is-zoomed');
    if (zoomed) zoomed.classList.remove('is-zoomed');
  });

  window.addEventListener('hashchange', render);

  /* ------------------------------------------------------------------ boot */

  var DATA_OK = false;

  /* The reader-facing "Data: …" badge is gone. The branch loadCourse took is
     still recorded, invisibly, because verify-runtime.js asserts on it: it is
     the only proof that loadCourse reported back and which path it took, and
     that proof is what caught the round-5 bundle that never ran at all. */
  function setDataNote(via, reason) {
    var el = document.getElementById('app');
    if (el && el.dataset) el.dataset.courseData = via;
  }

  loadCourse(function (via, reason) {
    DATA_OK = true;
    setDataNote(via, reason);
    if (via === 'none') {
      app.innerHTML = '<header class="page-head"><h1 tabindex="-1">Course data not found</h1></header>' +
        '<p>' + esc(reason) + '</p>';
      return;
    }
    render();
  });
})();
